target.css:
:root {
  --ink: #26372e;
  --muted: #68766b;
  --paper: #fffaf0;
  --cream: #f5ead2;
  --rind: #e8b552;
  --rind-dark: #b97924;
  --sage: #b9cbb1;
  --moss: #58715d;
  --coral: #d9694f;
  --line: #d9cdb7;
  --white: #ffffff;
}

* { box-sizing: border-box; }

.board {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 62px;
  padding: 12px 18px;
  border-bottom: 1px solid var(--line);
}

.heading { display: flex; align-items: baseline; gap: 11px; }

.eyebrow {
  margin: 0;
  color: var(--moss);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.2px;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.5px;
}

.status {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--sage);
  color: var(--ink);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.content {
  display: grid;
  grid-template-columns: 155px 1fr;
  min-height: 171px;
}

.wheel-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin: 0;
  padding: 12px;
  border-right: 1px solid var(--line);
  background: var(--cream);
}

.wheel-disk {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 94px;
  height: 94px;
  border: 7px solid var(--rind-dark);
  border-radius: 50%;
  outline: 2px solid var(--rind);
  outline-offset: 3px;
  background: var(--rind);
  color: var(--ink);
}

.wheel-disk strong { font-size: 30px; line-height: 0.9; }
.wheel-disk small { margin-top: 5px; font-size: 8px; font-weight: 800; line-height: 1.15; letter-spacing: 0.8px; text-align: center; }

figcaption {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
  text-align: center;
}

figcaption b { color: var(--moss); font-size: 9px; letter-spacing: 0.5px; }

.ledger {
  display: grid;
  grid-template-columns: 1fr 1.08fr;
  gap: 14px;
  padding: 14px 16px;
}

.metrics {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  margin: 0;
  padding: 0;
  list-style: none;
}

.metrics li {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
}

.metrics li:last-child { padding-bottom: 0; border-bottom: 0; }
.metrics span, .release p span { color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: 0.8px; }
.metrics b { font-size: 11px; line-height: 1.15; }

.tasting {
  padding: 10px;
  border-radius: 10px;
  background: var(--cream);
}

.tasting header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
h2 { margin: 0; font-size: 12px; }
.tasting header span { color: var(--moss); font-size: 9px; font-weight: 800; letter-spacing: 0.7px; }

.flavor { display: grid; grid-template-columns: 36px 1fr 12px; align-items: center; gap: 5px; margin: 5px 0; }
.flavor b { font-size: 10px; }
.flavor i { display: block; height: 5px; overflow: hidden; border-radius: 99px; background: var(--sage); }
.flavor em { display: block; width: 78%; height: 100%; border-radius: inherit; background: var(--moss); }
.flavor small { color: var(--moss); font-size: 10px; font-weight: 800; text-align: right; }
.bright em { width: 100%; background: var(--coral); }
.bright small { color: var(--coral); }

.release {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 51px;
  padding: 9px 14px 9px 18px;
  border-top: 1px solid var(--line);
  background: var(--white);
}

.release p { display: flex; flex-direction: column; gap: 2px; margin: 0; font-size: 11px; font-weight: 700; }
button {
  border: 0;
  border-radius: 8px;
  padding: 9px 11px;
  background: var(--ink);
  color: var(--white);
  font-size: 11px;
  font-weight: 800;
}
button b { margin-left: 7px; color: var(--rind); font-size: 15px; line-height: 0; }

